"""Jobs for the reading-room EXPLORATION thumbnails (eight concepts that differ in metaphor, composition and d-pad play, not in skin).
usage: python3 -I tools/readroomexplorejobs.py   -> writes source/work/concepts-readroom-explore/jobs-<id>.json, one job each, 1K, 16:9, one try.
Run each with: python3 -I tools/gen.py source/work/concepts-readroom-explore/jobs-<id>.json (the Pacific-day total checked before each)."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
WORK = os.path.join(ROOT, "source/work/concepts-readroom-explore"); os.makedirs(WORK, exist_ok=True)
MODEL = "gemini-3-pro-image"
REFS = [
    [os.path.join(ROOT, "source/work/concepts-readroom/ref-pod-loika.png"),
     "THE POD (project-owned game art): a wild seed pod, slate-blue with a round coral cap, pale vertical ribs and coral dots, standing on a small turned wooden dish. Keep its design exactly wherever the pod appears; never make it a jar, a vase, a lantern of metal, or an egg of another design."],
    [os.path.join(ROOT, "source/work/concepts-readroom/ref-loika.png"),
     "THE CREATURE (project-owned game art): the Loika the pod will become: a small round charcoal creature with a cream belly and muzzle, amber eyes, four stubby legs with pale toes and three green leaves on its head. Keep its design exactly; never invent another creature."],
    ["/home/user/miniaturebeasts/prototypes/ui/assets/masters/rooms/room-roots-idle-dusk-1024x568.png",
     "THE PAINTED LANGUAGE (one of our signed Vivarium room paintings, project-owned): its matte painterly miniature rendering, soft occlusion, warm golden light, cosy palette. Take the treatment and the warmth only, none of its objects."],
]
HEAD = "Paint the WHOLE screen of a cosy handheld creature-keeping game, 16:9, a mood-and-layout thumbnail for a concept: the READING ROOM, where the player opens up a wild pod (a seed pod with a creature's genome sleeping inside) one surprise at a time. The feeling: a pod is RICH IN SURPRISES, there is more inside than you can see, and each read brings one out into the light. "
TAIL = "\nLIGHT AND FINISH: warm key light, warm bounce, soft ambient occlusion, soft contact shadows. Matte, hand-painted miniature finish like the painted reference, cosy and warm, real depth; low saturation everywhere except the pod's inner light and the surprises. No gloss, no chrome, no plastic, no neon, no sci-fi interface, no holograms, nothing childish.\nNO text, letters, digits, numbers, logos, buttons, panels, boxes or icons anywhere (the game types its words later). No frame, no border, no vignette; the picture fills the canvas edge to edge."
CONCEPTS = {
 "lens": "CONCEPT: THE LENS. The player looks INTO the pod through a big round brass-rimmed magnifying glass, and inside it a tiny world comes into focus. COMPOSITION: the pod, huge, fills the lower two thirds of the screen, slate-blue shell, coral cap at the top, lit from behind by a warm lamp so its shell glows amber between the ribs. Across the middle of the pod a large round lens (about half the screen's height) is held by a hand at the right edge, its brass rim catching the light. THROUGH the lens, sharp and bright: a tiny lit world deep inside the pod, a small mossy meadow with a brook, dusk sky, and in its middle the small Loika, half of it painted in colour and half still a soft grey fog. OUTSIDE the lens, blurred on the pod's shell, many soft out-of-focus coloured shapes drift like things seen through frosted glass: a lock of russet fur, an amber eye, a leaf, a paw, a curl of tail; they are blurry and many, which says 'plenty still unseen'. The room around the pod is a dark warm study, soft bokeh.",
 "lantern": "CONCEPT: THE LANTERN. The pod is hung from a hook like a lantern in a dark round room, and its inner light throws big soft SHADOW-SHAPES of what it holds onto the walls all around. COMPOSITION: the pod hangs from a cord at the top centre of the screen, small (about a quarter of the screen's height), the only light source, glowing warm amber from within between its ribs, its coral cap and dots kept. The whole screen around it is the curved plaster wall of a cosy round room going to shadow, and on it, huge and soft, five or six shadow silhouettes cast outward from the pod like a magic lantern: a tuft of fur, a round eye, a paw with toes, a leaf, a curling tail, a pair of ears; each shadow is a different dark warm tone with a soft edge. On the wooden floor at the bottom centre, small, stands the Loika, looking up, half painted in colour and half grey fog, with one shadow (the fur) just landing on its back and turning russet. A low wooden stool and a rug, nothing else.",
 "constellation": "CONCEPT: THE NIGHT SKY. The pod sits on a window sill at night, and the sky through the window holds its secrets as faint star-clusters; each read joins the stars into a picture that becomes a part of the creature. COMPOSITION: the whole screen is a big open window at night seen from inside a warm room: a deep blue-violet sky with soft clouds fills the top three quarters. In the sky, five faint unjoined star-clusters glitter, each a loose scatter of warm little stars, one cluster already JOINED by thin golden lines into a constellation shaped like a lock of fur with a soft painted picture of russet fur glowing inside it. Along the bottom quarter a wooden window sill: at the left the pod on its dish, small, glowing softly from within, slate-blue, coral cap; at the right the small Loika sits looking up at the sky, half painted in colour and half grey fog, a single golden thread of light drifting down from the joined constellation to its back. A warm curtain at one edge, a candle's glow from inside the room.",
 "sprout": "CONCEPT: THE SPROUT. The pod is planted, and each read sprouts a new stem whose bud opens into a part of the creature: the creature grows like a plant. COMPOSITION: at the bottom centre a terracotta pot of dark earth sits on a warm wooden sill, and the pod is half-buried in it like a bulb, slate-blue, coral cap showing, glowing softly from within. From its cap a soft green stem rises up the middle of the screen with several branching stems, and on them six CLOSED buds, plump and glowing faintly through their green sepals in different hints of colour (russet, amber, cream, ash, green), slightly translucent so a shape inside each is just guessed. One bud has OPENED into a soft bloom and inside its petals, like a picture in a flower, is a lock of russet fur; a floating petal of light drifts from it. At the pot's foot, small, the Loika sits curled around the pot, half painted in colour and half grey fog. Behind, a warm plaster wall at evening with soft window light, a watering can, nothing else.",
 "shells": "CONCEPT: THE SHELLS. The pod opens like a nest of shells, one inside another, and every shell lifted shows the next painted surprise, down to the creature at the heart. COMPOSITION: on a warm wooden table at evening, big and centred, the pod stands OPEN: its top half (coral cap, slate-blue ribs) lifted and held up by an unseen hand at the top right, and inside it a smaller inner shell of a different warm colour, also open, and inside that a smaller one, like nesting shells, five rings in all seen in cross-section, each ring's inner face painted with a soft picture: russet fur on the outer, an amber eye on the next, pale toes, a leaf, a curl of tail, going inward and brighter. At the very heart, tiny and glowing, the Loika curled asleep in warm light, fully in colour. Two lifted shells already lie on the table to the left, face up, their pictures showing. Soft dust motes in the lamp light. A dark warm study wall behind.",
 "pool": "CONCEPT: THE POOL. Seen from above, the pod is a dark still pond at night, and the surprises swim under its surface like fish; the player swings a lantern over the water to draw one up. COMPOSITION: a top-down view: a round dark pool fills most of the screen, its rim the pod's own coral cap seen from above (a wide coral ring with pale ribs running out from it), its water deep slate-blue and very still, with the reflection of a warm lantern held just above the right edge (only the lantern's reflection and a hand's shadow show). UNDER the surface, half-hidden, soft lit shapes glide like koi: a russet lock of fur, an amber eye, a pale paw, a leaf, a curling tail, each a gentle coloured glow in the dark water with ripples over it. One shape, the fur, is BREAKING the surface in a ring of ripples and lifting into the lantern light. On the pool's near bank at the bottom left, on warm mossy stone, sits the small Loika looking into the water, half painted in colour and half grey fog, its reflection faint. Mossy warm stones and a few reeds round the rim.",
 "dream": "CONCEPT: THE DREAM. The grey creature sleeps curled around its pod, and its dreams rise from the pod as soft bubbles, each holding one surprise; the player catches a bubble and the dream comes true on the creature. COMPOSITION: in the lower third, big, on a round woven rug by a warm hearth glow, the Loika lies asleep curled around the pod, which rests against its belly like an egg being kept warm, slate-blue, coral cap, glowing softly from within. The creature is mostly grey fog with only its cream belly and one russet patch on its back painted in colour. From the pod's cap, a stream of soft round DREAM BUBBLES rises up through the upper two thirds of the dark cosy room, drifting and wobbling, each bubble lit from inside with a different soft picture: a lock of russet fur, an amber eye, pale toes, a leaf, a curl of tail, a pair of ears; the highest ones large and near, the lowest small and just leaving the pod. One bubble is bursting into a shower of warm sparks that fall toward the creature's back. A dark warm plaster wall with a small round window of night sky, a stool, a mug, nothing else.",
 "cabinet": "CONCEPT: THE CABINET. The pod is the top of a tiny naturalist's cabinet of curiosities: a wooden chest of many small drawers under it, and every drawer pulled out holds one surprise on a bed of moss. COMPOSITION: centred on a dark warm study wall at evening, a small antique wooden cabinet (about two thirds of the screen's height) with twelve small drawers of different sizes with little brass ring pulls, warm honey wood, slightly crooked and hand-made. On top of the cabinet stands the pod on its dish, slate-blue, coral cap, glowing softly from within, lit by a small brass lamp beside it. THREE drawers are pulled out at different depths and each holds, on a bed of moss, one lit treasure: a lock of russet fur, an amber glass eye, a green leaf; the other drawers are CLOSED and from the gaps around them leaks a faint warm glow in different colours, so the closed drawers plainly hold more. On the floor at the bottom right stands the small Loika on its hind legs, forepaws on a low drawer, peeking in, half painted in colour and half grey fog. A rug, dust in the lamp light, nothing else.",
}
for cid, text in CONCEPTS.items():
    job = {"name": f"concepts-readroom-explore/{cid}", "model": MODEL, "aspect": "16:9", "size": "1K", "tries": 1, "refs": REFS, "prompt": HEAD + text + TAIL}
    json.dump([job], open(os.path.join(WORK, f"jobs-{cid}.json"), "w"), indent=1)
    print("wrote", f"jobs-{cid}.json")
